SELECT COUNT(*)
FROM members
WHERE email = #{email}

SELECT COUNT(*)
FROM region
WHERE region_id = #{regionId}

SELECT COUNT(*)
FROM members
WHERE nickname = #{nickname}

SELECT COUNT(*)
FROM interest
WHERE interest_id = #{interestId}

SELECT COUNT(*)
FROM term
WHERE term_id = #{termId}

SELECT COUNT(*)
FROM members
WHERE nickname = #{nickname}
AND member_id <> #{memberId}

mapper.update:
UPDATE members
SET nickname = #{nickname}
WHERE member_id = #{memberId}
AND deleted_at IS NULL

UPDATE members
SET profile_img_url = #{profileImageUrl, jdbcType=VARCHAR}
WHERE member_id = #{memberId}
    AND deleted_at IS NULL
